package com.vandorlabs.neoforge.screen;
import com.vandorlabs.neoforge.ModernFinishCatalog;
import java.util.*;
/** Source-generated names and aliases. Runtime sprites are resolved elsewhere and never retained here. */
public final class NativeScreenCatalog implements NativeScreenEntity.Catalog {
 public record Input(String id,boolean animated,int frames){}
 public record Option(String key,String bare,String framed,String label){public boolean hasPair(){return !bare.equals(framed);}}
 private record Choice(boolean framed,int bare){}
 private record Data(String[] screens,Input[] inputs,String[] framed,Map<String,String> pairs,Option[] options,Choice[] choices,Map<String,String> screenAliases,Map<String,String> inputAliases,Map<String,Integer> sources,int defaultHousing,int frame,Map<String,String> legacyAliases){}
 public static final NativeScreenCatalog INSTANCE=load();private final Data data;private final Set<String> screens,inputs,framed;private final List<String> screenNames,inputNames;private final List<Option> options;private final Map<String,Integer> inputFrames;
 private NativeScreenCatalog(Data data){this.data=data;screens=Set.copyOf(Arrays.asList(data.screens));screenNames=List.copyOf(Arrays.asList(data.screens));List<String> names=new ArrayList<>();Map<String,Integer> frames=new HashMap<>();for(Input input:data.inputs){names.add(input.id);frames.put(input.id,input.animated?Math.max(1,input.frames):1);}inputs=Set.copyOf(names);inputNames=List.copyOf(names);inputFrames=Map.copyOf(frames);framed=Set.copyOf(Arrays.asList(data.framed));List<Option> ordered=new ArrayList<>(Arrays.asList(data.options));ordered.sort(Comparator.comparing(Option::label,String.CASE_INSENSITIVE_ORDER));options=List.copyOf(ordered);}
 private static NativeScreenCatalog load(){var stream=NativeScreenCatalog.class.getResourceAsStream("/assets/vandorlabs/data/screen_catalog.json");if(stream==null)throw new IllegalStateException("Missing native screen catalog");try(var reader=new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)){return new NativeScreenCatalog(new com.google.gson.Gson().fromJson(reader,Data.class));}catch(java.io.IOException failure){throw new ExceptionInInitializerError(failure);}}
 public List<String> screens(){return screenNames;}public List<String> inputs(){return inputNames;}public List<Option> options(){return options;}public Map<String,String> legacyAliases(){return Map.copyOf(data.legacyAliases);}
 public boolean validScreen(String id){return id!=null&&screens.contains(id);}public boolean validInput(String id){return id!=null&&inputs.contains(id);}public String defaultInput(){return inputNames.get(0);}public String canonicalScreen(String id){return id==null?null:data.screenAliases.getOrDefault(id,id);}public String canonicalInput(String id){return id==null?null:data.inputAliases.getOrDefault(id,id);}public int inputFrames(String id){return id==null?1:inputFrames.getOrDefault(canonicalInput(id),1);}
 public boolean legacyFramed(String id){return id!=null&&framed.contains(id);}public String pairedBare(String id){return id==null?null:data.pairs.get(id);}public boolean framedChoice(int value){return value>=0&&value<data.choices.length&&data.choices[value].framed;}public int bareChoice(int value){return value>=0&&value<data.choices.length?data.choices[value].bare:value;}
 public int defaultHousing(){return data.defaultHousing;}public int defaultFrame(){return data.frame;}public boolean validMaterial(int value){return ModernFinishCatalog.validChoice(value);}public int material(int value){return ModernFinishCatalog.storedChoice(value);}public boolean validFrame(int value){return com.vandorlabs.neoforge.door.NativeDoorSettings.frame(value);}public boolean validFrameSurface(int value){return com.vandorlabs.neoforge.door.NativeDoorSettings.surface(value);}
 public int sourceChoice(String source){return source==null?0:data.sources.getOrDefault(source,0);}public int screenArtwork(String id){return sourceChoice(canonicalScreen(id)+"_static");}public int inputArtwork(String id){return sourceChoice("console_inputs/"+canonicalInput(id)+"_static");}
}
